Method.Source:
/// <summary>
/// Initializes the query ranges for the data source.
/// </summary>
void init()
{
    QueryBuildRange criteriaSalesOrder;

    next init();

    criteriaSalesOrder = this.query().dataSourceName(this.name()).addRange(fieldNum(InventTableModule, ModuleType));
    criteriaSalesOrder.value(queryValue(ModuleInventPurchSales::AVARUMSalesForProductVariants));
    criteriaSalesOrder.status(RangeStatus::Hidden);
}

/// <summary>
/// Initializes the values of the extended fields.
/// </summary>
void initValue()
{
    FormDataSource inventDimCombDS;
    InventDimCombination inventDimComb;
    FormDataSource inventTableModuleDS;
    InventTableModule inventTableModule;
    EcoResDistinctProductVariant productVariant;

    next initValue();

    inventDimCombDS = this.formRun().dataSource(formDataSourceStr(EcoResProductVariantsPerCompany, InventDimCombination));
    inventDimComb = inventDimCombDS.cursor();

    inventTableModuleDS = this;
    inventTableModule = inventTableModuleDS.cursor();

    productVariant = EcoResDistinctProductVariant::find(inventDimComb.DistinctProductVariant);

    inventTableModule.ItemId = productVariant.DisplayProductNumber;
    inventTableModule.ModuleType = ModuleInventPurchSales::AVARUMSalesForProductVariants;
}

/// <summary>
/// Validates the write operation.
/// </summary>
/// <returns>True if the write operation is valid; otherwise, false.</returns>
boolean validateWrite()
{
    return true;
}

/// <summary>
/// Writes the data source.
/// </summary>
void write()
{
    FormDataSource inventDimCombDS;
    InventDimCombination inventDimComb;
    FormDataSource inventTableModuleDS;
    InventTableModule inventTableModule;
    EcoResDistinctProductVariant productVariant;

    inventDimCombDS = this.formRun().dataSource(formDataSourceStr(EcoResProductVariantsPerCompany, InventDimCombination));
    inventDimComb = inventDimCombDS.cursor();

    inventTableModuleDS = this.formRun().dataSource(formDataSourceStr(EcoResProductVariantsPerCompany, AVASalesForProductVariants));
    inventTableModule = inventTableModuleDS.cursor();

    if (!inventTableModule || !inventTableModule.ItemId)
    {
        productVariant = EcoResDistinctProductVariant::find(inventDimComb.DistinctProductVariant);

        inventTableModule.ItemId = productVariant.DisplayProductNumber;
        inventTableModule.ModuleType = ModuleInventPurchSales::AVARUMSalesForProductVariants;
    }

    if (inventTableModule.validateWrite())
    {
        next write();
    }
}
